1	package masker
2	
3	import (
4		"fmt"
5		"reflect"
6		"strings"
7		"sync"
8	)
9	
10	const tagName = "mask"
11	
12	// MaskerType is a string type for masker type
13	type MaskerType string
14	
15	// MaskerType constants
16	const (
17		MaskerTypeNone      MaskerType = "none"
18		MaskerTypePassword  MaskerType = "password"
19		MaskerTypeName      MaskerType = "name"
20		MaskerTypeAddress   MaskerType = "addr"
21		MaskerTypeEmail     MaskerType = "email"
22		MaskerTypeMobile    MaskerType = "mobile"
23		MaskerTypeTel       MaskerType = "tel"
24		MaskerTypeID        MaskerType = "id"
25		MaskerTypeCredit    MaskerType = "credit"
26		MaskerTypeURL       MaskerType = "url"
27		MaskerTypeAbuse     MaskerType = "abuse"
28		MaskerTypeStruct    MaskerType = "struct"
29		MaskerTypeAll       MaskerType = "all"
30		MaskerTypeMapStruct MaskerType = "mapstruct"
31	)
32	
33	// Masker is an interface for masking sensitive data
34	type Masker interface {
35		Marshal(string, string) string
36	}
37	
38	// MaskerMarshaler is a masker marshaler.
39	// All exported methods are safe for concurrent use.
40	// Direct access to the Maskers field is NOT concurrency-safe; use Register/Get instead.
41	type MaskerMarshaler struct {
42		mu      sync.RWMutex
43		Maskers map[MaskerType]Masker
44		masker  string // default masker
45	}
46	
47	// Marshal returns a masked value by masker type
48	// It is used for masking sensitive data
49	// Example:
50	//
51	//	m := masker.NewMaskerMarshaler()
52	//	log.Println(m.Marshal(masker.MaskerTypeNone, "none"))                               // none <nil>
53	//	log.Println(m.Marshal(masker.MaskerTypePassword, "password"))                       // ************** <nil>
54	//	log.Println(m.Marshal(masker.MaskerTypeName, "name"))                               // n**e <nil>
55	//	log.Println(m.Marshal(masker.MaskerTypeAddress, "address"))                         // addres****** <nil>
56	//	log.Println(m.Marshal(masker.MaskerTypeEmail, "email"))                             // ema**** <nil>
57	//	log.Println(m.Marshal(masker.MaskerTypeMobile, "mobile"))                           // mobi*** <nil>
58	//	log.Println(m.Marshal(masker.MaskerTypeTel, "tel"))                                 // tel <nil>
59	//	log.Println(m.Marshal(masker.MaskerTypeID, "id"))                                   // id**** <nil>
60	//	log.Println(m.Marshal(masker.MaskerTypeCredit, "4111111111111111"))                 // 411111******1111 <nil>
61	//	log.Println(m.Marshal(masker.MaskerTypeURL, "http://john:password@localhost:3000")) // http://john:xxxxx@localhost:3000 <nil>
62	func (m *MaskerMarshaler) Marshal(t MaskerType, value string) (string, error) {
63		m.mu.RLock()
64		defer m.mu.RUnlock()
65		if result, matched, err := parseGenericMask(m.masker, string(t), value); matched {
66			return result, err
67		}
68		masker, ok := m.Maskers[t]
69		if !ok {
70			return "", fmt.Errorf("masker %v not found", t)
71		}
72		return masker.Marshal(m.masker, value), nil
73	}
74	
75	// Register adds a masker by masker type
76	// It is used for adding or override a masker by masker type
77	// Example:
78	//
79	//	m := masker.NewMaskerMarshaler()
80	//	m.Register(masker.MaskerTypePassword, &PasswordMasker{})
81	//	log.Println(m.List()) // [password name addr email tel id url none mobile credit]
82	func (m *MaskerMarshaler) Register(t MaskerType, masker Masker) {
83		m.mu.Lock()
84		defer m.mu.Unlock()
85		m.Maskers[t] = masker
86	}
87	
88	// Unregister removes a masker by masker type
89	// It is used for removing a masker by masker type
90	// Example:
91	//
92	//	m := masker.NewMaskerMarshaler()
93	//	m.Unregister(masker.MaskerTypePassword)
94	//	log.Println(m.List()) // [name addr email tel id url none mobile credit]
95	func (m *MaskerMarshaler) Unregister(t MaskerType) {
96		m.mu.Lock()
97		defer m.mu.Unlock()
98		delete(m.Maskers, t)
99	}
100	
101	// Get returns a masker by masker type
102	// It is used for getting a masker by masker type
103	// Example:
104	//
105	//	m := masker.NewMaskerMarshaler()
106	//	masker, _ := m.Get(masker.MaskerTypePassword)
107	//	log.Println(masker) // &{PasswordMasker}
108	func (m *MaskerMarshaler) Get(t MaskerType) (Masker, error) {
109		m.mu.RLock()
110		defer m.mu.RUnlock()
111		masker, ok := m.Maskers[t]
112		if !ok {
113			return nil, fmt.Errorf("masker %v not found", t)
114		}
115		return masker, nil
116	}
117	
118	// List returns a list of masker types
119	// It is used for listing all masker types
120	// Example:
121	//
122	//	m := masker.NewMaskerMarshaler()
123	//	log.Println(m.List()) // [password name addr email tel id url none mobile credit]
124	func (m *MaskerMarshaler) List() []MaskerType {
125		m.mu.RLock()
126		defer m.mu.RUnlock()
127		var list []MaskerType
128		for t := range m.Maskers {
129			list = append(list, t)
130		}
131		return list
132	}
133	
134	func (m *MaskerMarshaler) SetMasker(masker string) {
135		m.mu.Lock()
136		defer m.mu.Unlock()
137		m.masker = masker
138	}
139	
140	// Struct must input a interface{}, add tag mask on struct fields, after Struct(), return a pointer interface{} of input type and it will be masked with the tag format type
141	//
142	// Limitation:
143	//   - Cyclic object graphs are not specially handled. Self-referencing structures can
144	//     recurse indefinitely when using `mask:"struct"` or `mask:"mapstruct"`.
145	//   - Avoid cyclic references in masking paths.
146	//
147	// Example:
148	//
149	//	type Foo struct {
150	//		Name      string `mask:"name"`
151	//		Email     string `mask:"email"`
152	//		Password  string `mask:"password"`
153	//		ID        string `mask:"id"`
154	//		Address   string `mask:"addr"`
155	//		Mobile    string `mask:"mobile"`
156	//		Telephone string `mask:"tel"`
157	//		Credit    string `mask:"credit"`
158	//		URL       string `mask:"url"`
159	//		Foo       *Foo   `mask:"struct"`
160	//	}
161	//
162	//	func main() {
163	//		m := masker.NewMaskerMarshaler()
164	//		log.Println(m.List()) // [password name addr email tel id url none mobile credit]
165	//		foo1 := &Foo{
166	//			Name:      "John Doe",
167	//			Email:     "john@gmail.com",
168	//			Password:  "password",
169	//			ID:        "1234567890",
170	//			Address:   "123 Main St",
171	//			Mobile:    "1234567890",
172	//			Telephone: "1234567890",
173	//			Credit:    "4111111111111111",
174	//			URL:       "http://john:password@localhost:3000",
175	//			Foo: &Foo{
176	//				Name:      "John Doe",
177	//				Email:     "john@gmail.com",
178	//				Password:  "password",
179	//				ID:        "1234567890",
180	//				Address:   "123 Main St",
181	//				Mobile:    "1234567890",
182	//				Telephone: "1234567890",
183	//				Credit:    "4111111111111111",
184	//				URL:       "http://john:password@localhost:3000",
185	//			},
186	//		}
187	//
188	//		foo2, _ := m.Struct(foo1)
189	//
190	//		log.Println(foo1) // &{John Doe john@gmail.com password 1234567890 123 Main St 1234567890 1234567890 4111111111111111 http://john:password@localhost:3000 0xc0000001e0}
191	//		log.Println(foo1.Foo) // &{John Doe john@gmail.com password 1234567890 123 Main St 1234567890 1234567890 4111111111111111 http://john:password@localhost:3000 <nil>}
192	//		log.Println(foo2) // &{J**n D**e joh****@gmail.com ************** 123456**** 123 Ma****** 1234***890 (12)3456-**** 411111******1111 http://john:xxxxx@localhost:3000 0xc000000320}
193	//		log.Println(foo2.(*Foo).Foo) // &{J**n D**e joh****@gmail.com ************** 123456**** 123 Ma****** 1234***890 (12)3456-**** 411111******1111 http://john:xxxxx@localhost:3000 <nil>}
194	//	}
195	func (m *MaskerMarshaler) Struct(s interface{}) (interface{}, error) {
196		if s == nil {
197			return nil, fmt.Errorf("input is nil")
198		}
199	
200		var selem, tptr reflect.Value
201	
202		st := reflect.TypeOf(s)
203		sv := reflect.ValueOf(s)
204	
205		actualKind := st.Kind()
206		if actualKind == reflect.Ptr {
207			if sv.IsNil() {
208				return nil, fmt.Errorf("input is nil pointer")
209			}
210			actualKind = st.Elem().Kind()
211		}
212		if actualKind != reflect.Struct {
213			return nil, fmt.Errorf("input must be a struct or pointer to struct, got %v", actualKind)
214		}
215	
216		if st.Kind() == reflect.Ptr {
217			tptr = reflect.New(st.Elem())
218			selem = sv.Elem()
219		} else {
220			tptr = reflect.New(st)
221			selem = sv
222		}
223	
224		for i := 0; i < selem.NumField(); i++ {
225			if !selem.Type().Field(i).IsExported() {
226				continue
227			}
228			mtag := selem.Type().Field(i).Tag.Get(tagName)
229			if len(mtag) == 0 {
230				tptr.Elem().Field(i).Set(selem.Field(i))
231				continue
232			}
233	
234			switch selem.Field(i).Type().Kind() {
235			default:
236				tptr.Elem().Field(i).Set(selem.Field(i))
237			case reflect.String:
238				v, err := m.Marshal(MaskerType(mtag), selem.Field(i).String())
239				if err != nil {
240					return nil, err
241				}
242				tptr.Elem().Field(i).SetString(v)
243			case reflect.Struct:
244				if MaskerType(mtag) == MaskerTypeStruct {
245					_t, err := m.Struct(selem.Field(i).Interface())
246					if err != nil {
247						return nil, err
248					}
249					tptr.Elem().Field(i).Set(reflect.ValueOf(_t).Elem())
250				} else {
251					tptr.Elem().Field(i).Set(selem.Field(i))
252				}
253			case reflect.Ptr:
254				if selem.Field(i).IsNil() {
255					continue
256				}
257				if MaskerType(mtag) == MaskerTypeStruct {
258					_t, err := m.Struct(selem.Field(i).Interface())
259					if err != nil {
260						return nil, err
261					}
262					tptr.Elem().Field(i).Set(reflect.ValueOf(_t))
263				} else {
264					tptr.Elem().Field(i).Set(selem.Field(i))
265				}
266			case reflect.Map:
267				if selem.Field(i).IsNil() {
268					continue
269				}
270				if MaskerType(mtag) != MaskerTypeMapStruct {
271					tptr.Elem().Field(i).Set(selem.Field(i))
272					continue
273				}
274	
275				maskedMap := reflect.MakeMapWithSize(selem.Field(i).Type(), selem.Field(i).Len())
276				iter := selem.Field(i).MapRange()
277				for iter.Next() {
278					v := iter.Value()
279					maskedValue, err := m.maskMapStructValue(v)
280					if err != nil {
281						return nil, err
282					}
283	
284					maskedMap.SetMapIndex(iter.Key(), maskedValue)
285				}
286				tptr.Elem().Field(i).Set(maskedMap)
287				continue
288	
289			case reflect.Slice:
290				if selem.Field(i).IsNil() {
291					continue
292				}
293				switch {
294				case selem.Field(i).Type().Elem().Kind() == reflect.String:
295					orgval := selem.Field(i).Interface().([]string)
296					newval := make([]string, len(orgval))
297					for i, val := range selem.Field(i).Interface().([]string) {
298						v, err := m.Marshal(MaskerType(mtag), val)
299						if err != nil {
300							return nil, err
301						}
302						newval[i] = v
303					}
304					tptr.Elem().Field(i).Set(reflect.ValueOf(newval))
305				case selem.Field(i).Type().Elem().Kind() == reflect.Struct && MaskerType(mtag) == MaskerTypeStruct:
306					newval := reflect.MakeSlice(selem.Field(i).Type(), 0, selem.Field(i).Len())
307					for j, l := 0, selem.Field(i).Len(); j < l; j++ {
308						_n, err := m.Struct(selem.Field(i).Index(j).Interface())
309						if err != nil {
310							return nil, err
311						}
312						newval = reflect.Append(newval, reflect.ValueOf(_n).Elem())
313					}
314					tptr.Elem().Field(i).Set(newval)
315				case selem.Field(i).Type().Elem().Kind() == reflect.Ptr && MaskerType(mtag) == MaskerTypeStruct:
316					newval := reflect.MakeSlice(selem.Field(i).Type(), 0, selem.Field(i).Len())
